breach.segment:
// Ignore nodes and conditions that stopped reporting more than 5 minutes before their cluster's newest sample
WHERE last_seen >= cluster_newest - 5 minutes
// MemoryPressure, DiskPressure, PIDPressure, NetworkUnavailable and node-problem-detector conditions are problems when True
| WHERE condition_status == "True"
| KEEP resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name,
       resource.attributes.node_name, attributes.condition, condition_status, last_seen
